inline std::string Join(std::initializer_list<std::string_view> chunks)
{
    std::string text;
    for (auto chunk : chunks)
    {
        if (chunk.size() > 1024 * 1024 - text.size()) throw std::length_error("literal fixture byte budget");
        text.append(chunk);
    }
    return text;
}
